# Restore Default SSD/Defrag Settings Write-Host "Restoring default defrag and SSD settings..." -ForegroundColor Cyan # Re-enable automatic defragmentation task Enable-ScheduledTask -TaskName "\Microsoft\Windows\Defrag\ScheduledDefrag" -ErrorAction SilentlyContinue Write-Host " Automatic defrag scheduled task re-enabled." -ForegroundColor Gray # Re-enable Storage Tiers optimization Enable-ScheduledTask -TaskName "\Microsoft\Windows\Storage Tiers Management\Storage Tiers Optimization" -ErrorAction SilentlyContinue Write-Host " Storage Tiers optimization task re-enabled." -ForegroundColor Gray # TRIM is left enabled as it's the optimal default Write-Host "Default settings restored. TRIM remains enabled (recommended)." -ForegroundColor Green